  "privacy.seeVenueBody": "场馆职员可查看您的预订、付款状态以及您是否到场。他们无法查看其他场馆的顾客——这是由系统强制执行的，而不是靠客气请求。",
  "privacy.seePlayersLead": "您参与活动中的其他球友。",
  "privacy.seePlayersBody": "在公开球局中，其他人可看到您的名字和水平。在锦标赛或联赛中，您的姓名会出现在对阵表和积分表上。在联赛中，同一赛季同组的球友也能看到您的手机号码，以便安排比赛——加入前会先告知您。",
