  "privacy.doTitle": "您可以怎么做",
  "privacy.doSeeLead": "查看资料。",
  "privacy.doSeeBody1": "登录后，在账户页面使用",
  "privacy.doSeeLink": "下载副本",
  "privacy.doSeeBody2": "功能，即可将您账户下的所有资料下载为一个文件。在柜台购买的项目——次卡、会员、入门指导——是以手机号码而非登录账户记录的，请向场馆索取：他们会当面核实您的身份，这是网站做不到的。",
  "privacy.doFixLead": "更正资料。",
  "privacy.doFixBody": "请联系场馆——他们可以更改预订上的姓名或号码。",
  "privacy.doEraseLead": "删除资料。",
  "privacy.doEraseLink": "注销我的账户",
  "privacy.doEraseBody": "（在同一页面）。通过账户进行的未来预订将被取消，过往预订上的姓名也会被删除。以访客身份（未登录）进行的预订不与账户关联——请联系场馆删除。若场馆仍欠您储值、次卡或会员，请先处理：我们不会删除记录这笔钱属于谁的资料。",
  "privacy.doGuestLead": "完全不用账户预订。",
  "privacy.doGuestBody": "只需姓名和手机号码即可，这样就没有需要注销的账户。",
  "privacy.contactTitle": "联系谁",
  "privacy.contactBody": "{name}对本网站所持有的您的资料负责。如需查询所持有的资料、要求更正，或就资料的使用方式提出投诉，请写信至：",
  "privacy.draftBodyNamed": "本声明描述的是系统的实际运作方式，这是最难的部分——但它并非法律意见。它是根据{dataAct}撰写的，但尚无律师审阅过它或其任何译本。在接受真实顾客的预订前，请律师审阅。",
  "privacy.draftTitle": "本网站上线前",
  "privacy.draftBody": "本声明描述的是系统的实际运作方式，这是最难的部分——但它并非法律意见，也尚未完成。它是根据{dataAct}撰写的，但尚无律师审阅过它或其任何译本，也还没有指定的联系人。在接受真实顾客的预订前，请补上这两项，并请律师审阅。",
