  "gcap.passes-online.title": "在线出售次卡",
  "gcap.passes-online.blurb": "客户在您的页面上购买您选定的次卡，并通过您的收款账户付款；付款到账后才发放次卡。",
  "fit.s.pass-sell.x.online": "经理也可以在线出售次卡：客户在场馆页面购买，并通过场馆的收款账户付款，付款后才发放次卡。",
