  "pn1.intro": "抽签表、赛果、积分榜、阶梯榜和实时页面默认以名字加下一个名字的首字母显示儿童，例如“Aina L.”，除非您在下方允许显示全名。这完全由您决定：场馆不能代您决定，报名参赛也不代表同意。",
